		t.Errorf("response headers of the input changed: %v", raw.Header)
	}
	if string(raw.Body) != `{"token" : "abc"}` {
		t.Errorf("body of the input changed: %q", raw.Body)
	}
}

func TestRedactBodies(t *testing.T) {
