	htmlRaw.Status = 404
	htmlRaw.Header = rawHeader("Server", "Nexus/3.98.1-01 (COMMUNITY)", "Content-Type", "text/html;charset=utf-8", "Content-Length", "109")
	htmlRaw.Body = []byte(rawHTML)

	emptyRaw := rawJSONExchange("")
	emptyRaw.Status = 403
	emptyRaw.Body = nil

