// denylistEnv names a file, kept OUTSIDE the repository, with one term per
// line (names of an instance that must never appear in a fixture).
const denylistEnv = "DEVDESK_FIXTURE_DENYLIST"

const leakBaseName = "rest-repositories-docker-proxy--admin"

// leakBase is the real NX-03 answer the self-tests plant their leaks into: it has
// an Authorization line, a Host, a Server header, a JSON body with a URL and the
// bench's upstream service. The planted text is invented.
func leakBase(t *testing.T) string {
	t.Helper()
	fixtures, err := nexusfixture.Load("catalog")
	if err != nil {
		t.Fatal(err)
	}
	for _, f := range fixtures {
		if f.Name == leakBaseName {
			return string(nexusfixture.Format(f))
		}
	}
	t.Fatalf("the catalog campaign has no %s", leakBaseName)
	return ""
}

// plant replaces the one occurrence of old in base, failing when the base has
// moved and old is no longer there exactly once.
func plant(t *testing.T, base, old, repl string) string {
	t.Helper()
	if n := strings.Count(base, old); n != 1 {
		t.Fatalf("the base fixture holds %q %d times, want exactly once", old, n)
	}
	return strings.Replace(base, old, repl, 1)
}

func lineOf(data, needle string) int {
	i := strings.Index(data, needle)
	if i < 0 {
		return 0
	}
	return strings.Count(data[:i], "\n") + 1
}

const (
	hdrAuth   = "Authorization: Basic <redacted>\n"
	hdrHost   = "Host: 127.0.0.1:30481\n"
	hdrServer = "Server: Nexus/3.98.1-01 (COMMUNITY)\n"
	bodyOnl   = "  \"online\" : true,\n"
	bodyURL   = "\"url\" : \"http://127.0.0.1:30481/repository/docker-proxy\""
	bodyUp    = "\"remoteUrl\" : \"http://bench-upstream.nexus-bench.svc.cluster.local:5000\""
	metaAcct  = "# account: admin (nx-admin, Basic, sent preemptively)"
)

// bodyNote adds a JSON member after "online".
func bodyNote(member string) (old, repl string) { return bodyOnl, bodyOnl + "  " + member + ",\n" }

type leakCase struct {
	name    string
	old     string
	repl    string
	planted string   // the invented value: it must be found, and never echoed back
	exact   []string // extra terms handed to CheckLeaks
}

func leakCases() []leakCase {
	note := func(name, member, planted string) leakCase {
		old, repl := bodyNote(member)
		return leakCase{name: name, old: old, repl: repl, planted: planted}
	}
	exactOld, exactRepl := bodyNote(`"note" : "zz-exact-secret-91"`)
	b64Old, b64Repl := bodyNote(`"note" : "dXNlcjpwYXNzMTIz"`)
	return []leakCase{
		// Rule: Authorization other than Basic/Bearer <redacted>.
		{name: "authorization/basic value", old: hdrAuth, repl: "Authorization: Basic dXNlcjpwYXNzMTIz\n", planted: "dXNlcjpwYXNzMTIz"},
		{name: "authorization/lowercase name", old: hdrAuth, repl: "authorization: Basic dXNlcjpwYXNzMTIz\n", planted: "dXNlcjpwYXNzMTIz"},
		{name: "authorization/bearer value", old: hdrAuth, repl: "Authorization: Bearer REDACTED\n", planted: "opaque-token-4242"},
		{name: "authorization/unknown scheme", old: hdrAuth, repl: "Authorization: Digest response=\"d1g3st-77\"\n", planted: "d1g3st-77"},

		// Rule: Cookie, Set-Cookie, NXSESSIONID, X-Nexus-UI.
		{name: "cookie/request Cookie", old: hdrHost, repl: hdrHost + "Cookie: theme=dark; sid=c00kie-val-1\n", planted: "c00kie-val-1"},
		{name: "cookie/response Set-Cookie", old: hdrServer, repl: hdrServer + "Set-Cookie: sid=sessval-2; Path=/\n", planted: "sessval-2"},
		{name: "cookie/NXSESSIONID anywhere", old: hdrHost, repl: hdrHost + "X-Trace: NXSESSIONID=zz-nxsess-3\n", planted: "zz-nxsess-3"},
		{name: "cookie/X-Nexus-UI", old: hdrHost, repl: hdrHost + "X-Nexus-UI: ui-session-9\n", planted: "ui-session-9"},

		// Rule: a response header outside the allowlist.
		{name: "allowlist/unknown response header", old: hdrServer, repl: hdrServer + "X-Powered-By: some-proxy-77\n", planted: "some-proxy-77"},
		{name: "allowlist/Date", old: hdrServer, repl: hdrServer + "Date: Tue, 17 Nov 2026 10:00:00 GMT\n", planted: "Tue, 17 Nov 2026 10:00:00 GMT"},

		// Rule: a JWT-like value.
		note("jwt/in a value", `"note" : "eyJhbGciOiJIUzI1NiJ9.zz-payload-5"`, "eyJhbGciOiJIUzI1NiJ9.zz-payload-5"),
		{name: "jwt/in a header", old: hdrServer, repl: hdrServer + "Link: <eyJhbGciOiJIUzI1NiJ9zz6>; rel=\"next\"\n", planted: "eyJhbGciOiJIUzI1NiJ9zz6"},

		// Rule: a JSON secret key whose value is not <redacted>.
		note("json/token", `"token" : "zz-planted-token-1"`, "zz-planted-token-1"),
		note("json/token compact", `"token":"zz-planted-token-2"`, "zz-planted-token-2"),
		note("json/access_token", `"access_token" : "zz-planted-access-3"`, "zz-planted-access-3"),
		note("json/refresh_token", `"refresh_token" : "zz-planted-refresh-4"`, "zz-planted-refresh-4"),
		note("json/password", `"password" : "zz-planted-password-5"`, "zz-planted-password-5"),
		note("json/secret", `"secret" : "zz-planted-secret-6"`, "zz-planted-secret-6"),
		note("json/uploaderIp", `"uploaderIp" : "zz-planted-uploader-7"`, "zz-planted-uploader-7"),

		// Rule: a host in a URL or Host: outside AllowedHosts.
		{name: "host/URL in a body", old: bodyURL, repl: "\"url\" : \"http://nexus.zz-corp.example:8081/repository/docker-proxy\"", planted: "nexus.zz-corp.example"},
		{name: "host/Host header", old: hdrHost, repl: "Host: nexus.zz-corp.example:8081\n", planted: "nexus.zz-corp.example"},
		{name: "host/public IP", old: bodyURL, repl: "\"url\" : \"http://203.0.113.7:30481/repository/docker-proxy\"", planted: "203.0.113.7"},
		{name: "host/a namesake of the upstream is not the upstream", old: bodyUp, repl: "\"remoteUrl\" : \"http://bench-upstream.zz-other.svc.cluster.local:5000\"", planted: "zz-other"},
		{name: "host/https scheme", old: bodyURL, repl: "\"url\" : \"https://nexus.zz-tls.example/repository/docker-proxy\"", planted: "nexus.zz-tls.example"},

		// Rule: an RFC 1918 or link-local address.
		note("private/10.0.0.0/8", `"note" : "see 10.20.30.40"`, "10.20.30.40"),
		note("private/172.16.0.0/12", `"note" : "see 172.20.4.2"`, "172.20.4.2"),
		note("private/192.168.0.0/16", `"note" : "see 192.168.77.31"`, "192.168.77.31"),
		note("private/link-local", `"note" : "see 169.254.169.254"`, "169.254.169.254"),

		// Rule: internal names and local paths.
		note("internal/cluster context", `"note" : "prod-datomir-7"`, "prod-datomir-7"),
		note("internal/Linux home", `"note" : "/home/zed9/.cache/x"`, "/home/zed9/.cache/x"),
		note("internal/macOS home", `"note" : "/Users/zed9/Library"`, "/Users/zed9/Library"),
		note("internal/secrets file", `"note" : "/opt/zz9/secrets.json"`, "/opt/zz9/secrets.json"),
		note("internal/XDG variable", `"note" : "XDG_STATE_HOME=/zz9"`, "XDG_STATE_HOME=/zz9"),
		{name: "internal/in the commented header", old: metaAcct, repl: "# account: admin (cluster zz-datomir-8)", planted: "zz-datomir-8"},

		// Rule: an exact term (the recorder's passwords, the external deny list).
		{name: "exact/password", old: exactOld, repl: exactRepl, planted: "zz-exact-secret-91", exact: []string{"zz-exact-secret-91"}},
		{name: "exact/Basic encoding", old: b64Old, repl: b64Repl, planted: "dXNlcjpwYXNzMTIz", exact: []string{"unrelated-term", "dXNlcjpwYXNzMTIz"}},
	}
}

func TestLeakIsNeverTheMatchedText(t *testing.T) {
	typ := reflect.TypeFor[nexusfixture.Leak]()
	var fields []string
	for f := range typ.Fields() {
		fields = append(fields, f.Name)
	}
	slices.Sort(fields)
	if want := []string{"Fixture", "Line", "Rule"}; !slices.Equal(fields, want) {
		t.Errorf("Leak fields = %v, want exactly %v: a field for the matched text would put the secret in a test log", fields, want)
	}
}

func TestAllowedHostsAreLoopbackAndTheBenchUpstream(t *testing.T) {
	want := []string{"127.0.0.1", "bench-upstream.nexus-bench.svc.cluster.local"}
	if got := nexusfixture.AllowedHosts; !slices.Equal(got, want) {
		t.Errorf("AllowedHosts = %v, want %v", got, want)
	}

	// The upstream is the one the versioned descriptor names, not a second copy
	// that could drift from it; the descriptor's other hosts are not allowed.
	data, err := os.ReadFile(filepath.Join("..", "nexusbench", "testdata", "descriptor.example.json"))
	if err != nil {
		t.Fatal(err)
	}
	var d struct {
		Hosts        []string `json:"hosts"`
		Repositories []struct {
			RemoteURL string `json:"remoteUrl"`
		} `json:"repositories"`
	}
	if err := json.Unmarshal(data, &d); err != nil {
		t.Fatal(err)
	}
	var upstream string
	for _, r := range d.Repositories {
		if r.RemoteURL == "" {
			continue
		}
		u, err := url.Parse(r.RemoteURL)
		if err != nil {
			t.Fatal(err)
		}
		upstream = u.Hostname()
	}
	if upstream == "" || !slices.Contains(nexusfixture.AllowedHosts, upstream) {
		t.Errorf("the descriptor's proxy upstream %q is not in AllowedHosts %v", upstream, nexusfixture.AllowedHosts)
	}
	for _, h := range d.Hosts {
		if h != "127.0.0.1" && slices.Contains(nexusfixture.AllowedHosts, h) {
			t.Errorf("AllowedHosts holds %q, a LAN address of the descriptor: only loopback may be allowed", h)
		}
	}
}

func TestCheckLeaksEachRuleCatchesItsLeak(t *testing.T) {
	base := leakBase(t)
	if leaks := nexusfixture.CheckLeaks(leakBaseName, []byte(base), nil); len(leaks) != 0 {
		t.Fatalf("the unmodified base is not clean (%v): every case below would be meaningless", leaks)
	}

	rules := map[string]bool{}
	for _, tc := range leakCases() {
		t.Run(tc.name, func(t *testing.T) {
			data := plant(t, base, tc.old, tc.repl)
			line := lineOf(data, tc.planted)
			if line == 0 {
				t.Fatalf("the planted value %q is not in the fixture: the case is broken", tc.planted)
			}
			leaks := nexusfixture.CheckLeaks("planted--admin", []byte(data), tc.exact)
			if len(leaks) == 0 {
				t.Fatalf("no leak reported for a planted %s:\n%s", tc.name, data)
			}
			for _, l := range leaks {
				if l.Fixture != "planted--admin" {
					t.Errorf("Leak.Fixture = %q, want the name given to CheckLeaks", l.Fixture)
				}
				if l.Rule == "" {
					t.Errorf("a leak at line %d has no Rule", l.Line)
				}
				if l.Line != line {
					t.Errorf("leak %q reported at line %d, want line %d (the only line that changed)", l.Rule, l.Line, line)
				}
				rules[l.Rule] = true
			}
			if echoed := fmt.Sprintf("%+v %#v", leaks, leaks); strings.Contains(echoed, tc.planted) {
				t.Errorf("the leaks repeat the planted value: %s", echoed)
			}
		})
	}
	// The plan names nine rules (authorization, cookie/session, allowlist, JWT,
	// JSON secret, host, private address, internal name, exact term): the cases
	// above must not all be reported under fewer names.
	if len(rules) < 9 {
		t.Errorf("the planted leaks were reported under %d distinct Rule names (%v), want at least 9", len(rules), rules)
	}
}

