	metaAcct  = "# account: admin (nx-admin, Basic, sent preemptively)"
)

// bodyNote adds a JSON member after "online".
func bodyNote(member string) (old, repl string) { return bodyOnl, bodyOnl + "  " + member + ",\n" }

