func CheckLeaks(name string, data []byte, exact []string) []Leak {
	var out []Leak
	inResp := false
	for i, line := range strings.Split(string(data), "\n") {
		add := func(r string) { out = append(out, Leak{name, i + 1, r}) }
		if strings.HasPrefix(line, "HTTP/1.1 ") { inResp = true }
		if m := reHdr.FindStringSubmatch(line); m != nil && !strings.HasPrefix(line, "#") {
