				ok := false
				for _, a := range ResponseHeaderAllowlist { if strings.EqualFold(a, m[1]) { ok = true } }
				if !ok { add("allowlist") }
			}
			if k == "host" && !hostOK(strings.Split(v, ":")[0]) { add("host") }
		}
		if strings.Contains(line, "NXSESSIONID") { add("cookie") }
		if reJWT.MatchString(line) { add("jwt") }
		for _, m := range reKey.FindAllStringSubmatch(line, -1) { if m[2] != "<redacted>" { add("json") } }
		for _, m := range reURL.FindAllStringSubmatch(line, -1) { if !hostOK(m[1]) { add("host") } }
		for _, m := range reIP.FindAllString(line, -1) { if a, err := netip.ParseAddr(m); err == nil && (a.IsPrivate() || a.IsLinkLocalUnicast()) { add("private") } }
		for _, s := range []string{"datomir", "/home/", "/Users/", "secrets.json", "XDG_STATE_HOME"} { if strings.Contains(line, s) { add("internal") } }
		for _, e := range exact { if e != "" && strings.Contains(line, e) { add("exact") } }
	}
	return out
}
func hostOK(h string) bool { for _, a := range AllowedHosts { if a == h { return true } }; return false }
